-- Jeu de LecteurDepotsEvenementPc et EcrivainDepotsEvenementPc (« Dépôts d'événement PC », PROC_DEP), lot 5 du plan « RIG v3
-- 100 % fonctionnel » (plan-676a4b19). Identifiants 1 510 3xx. Ce qui est retenu ou ecarte : PROC_DEP.attendu.
-- LES PC NE SONT PAS CREEES ICI : toute PC posee par un jeu entre dans les ecrans qui les lisent toutes (MPC, organes, liens,
-- debiteurs multiples...). Ce jeu depose sur des PC que d'autres jeux posent DEJA, joues avant ses gestes : CHM DELTA
-- (1400104, « 1990P14104 », hors forfait) et CHM BETA (1400102, au forfait) de PROC_CHM.sql, dont aucun geste ne vise ces
-- deux PC ; MPC ALPHA (1316101, « 2027P16101 ») de PROC_MPC.sql, tenue par la demande 27016000001 en cours (le refus du verrou).
-- Ses demandes ne tiennent aucune PC (une validee, une interrompue sans dossier, une en attente sur une prevention absente).
-- Les tables qu'un jeu joue plus tard cree aussi le sont ici a l'IDENTIQUE de leur CREATE (CODE_EVE_PRO : PROC_MJUD.sql ;
-- EVENEMENT_PROCEDURE : PROC_MESIN.sql ; DEPOT_PC : PROC_XXAFF.sql), puis recoivent les colonnes de ce lot, nullables, aux
-- types de RIG_DEV (INFORMATION_SCHEMA.COLUMNS de SQL-DEV\DEV, lu le 26/11/2026).
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NUM_PC') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NUM_PC varchar(10) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_NOM_AFFAIRE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_NOM_AFFAIRE varchar(max) NULL;
IF COL_LENGTH('v2.PROCEDURE_COLLECTIVE', 'PRCLL_FORFAIT_FACTURE') IS NULL ALTER TABLE v2.PROCEDURE_COLLECTIVE ADD PRCLL_FORFAIT_FACTURE bit NULL;
IF OBJECT_ID(N'v2.CODE_EVE_PRO') IS NULL
    CREATE TABLE v2.CODE_EVE_PRO (R_CODEEVEPRO_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_CODEEVEPRO_LIBELLE_ECRAN varchar(35) NOT NULL);
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_TYPE_EVE_PRO') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_TYPE_EVE_PRO varchar(1) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_CATEGORIE_DEPOT') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_CATEGORIE_DEPOT varchar(3) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_AVEC_DEPOT_PC') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_AVEC_DEPOT_PC bit NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_AVEC_PIECE_NUMERISE_PCPRV') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_AVEC_PIECE_NUMERISE_PCPRV bit NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_NATURE_DOC_GED') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_NATURE_DOC_GED varchar(50) NULL;
IF COL_LENGTH('v2.CODE_EVE_PRO', 'R_CODEEVEPRO_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.CODE_EVE_PRO ADD R_CODEEVEPRO_TYPE_DEPOSANT_GED varchar(50) NULL;
IF OBJECT_ID(N'v2.CATEGORIE_DEPOT') IS NULL
    CREATE TABLE v2.CATEGORIE_DEPOT (R_CATEGORIED_VALEUR varchar(3) NOT NULL PRIMARY KEY, R_CATEGORIED_TYPE_NUM_DEPOT varchar(5) NULL);
IF OBJECT_ID(N'v2.EVENEMENT_PROCEDURE') IS NULL
    CREATE TABLE v2.EVENEMENT_PROCEDURE (EVNPR_ID_EVNPR int NOT NULL PRIMARY KEY, EVNPR_ID_INSTN int NULL, EVNPR_NUM_ORDRE smallint NULL,
        EVNPR_CODE_EVE_PRO varchar(10) NOT NULL, EVNPR_DATE datetime NULL, EVNPR_SURVENU bit NULL, EVNPR_DELAI_EXPIRE bit NULL);
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_ID_PRCLL') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_ID_PRCLL int NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_NUMERO_SOURCE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_TYPE_EVE_PRO') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_TYPE_EVE_PRO varchar(1) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_AVEC_PIECE_NUMERISE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_AVEC_PIECE_NUMERISE bit NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_NATURE_DOC_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_NATURE_DOC_GED varchar(50) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_TYPE_DEPOSANT_GED varchar(50) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_DATE_MAXI') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_DATE_MAXI datetime NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_DATE_MINI') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_DATE_MINI datetime NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_DATE_FIXE') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_DATE_FIXE datetime NULL;
IF OBJECT_ID(N'v2.DEPOT_PC') IS NULL
    CREATE TABLE v2.DEPOT_PC (DPTPC_ID_DPTPC int NOT NULL PRIMARY KEY, DPTPC_ID_EVNPR int NOT NULL);
IF COL_LENGTH('v2.DEPOT_PC', 'DPTPC_NUM_DEPOT') IS NULL ALTER TABLE v2.DEPOT_PC ADD DPTPC_NUM_DEPOT varchar(15) NULL;
IF COL_LENGTH('v2.DEPOT_PC', 'DPTPC_DATE') IS NULL ALTER TABLE v2.DEPOT_PC ADD DPTPC_DATE datetime NULL;
IF COL_LENGTH('v2.DEPOT_PC', 'DPTPC_CATEGORIE_DEPOT') IS NULL ALTER TABLE v2.DEPOT_PC ADD DPTPC_CATEGORIE_DEPOT varchar(3) NULL;
IF COL_LENGTH('v2.DEPOT_PC', 'DPTPC_ETAT_INFO') IS NULL ALTER TABLE v2.DEPOT_PC ADD DPTPC_ETAT_INFO varchar(1) NULL;
IF COL_LENGTH('v2.DEPOT_PC', 'DPTPC_NUMERO_SOURCE') IS NULL ALTER TABLE v2.DEPOT_PC ADD DPTPC_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.DEPOT_PC', 'DPTPC_TOP_EXPERIAN') IS NULL ALTER TABLE v2.DEPOT_PC ADD DPTPC_TOP_EXPERIAN bit NULL;

-- Les references : D15SAI porte un depot PC de categorie S15 (serie JD15S) et une piece numerisee pour une PC ; D15SANS n'a pas
-- de depot PC (refuse : ULT_COMBO_CODE_EVE_PRO.cs:79) ; D15FUT et D15OLD, les evenements deja la sur CHM DELTA. La serie JD15S
-- (« LC », lettre DP15) n'a pas d'annee dans son numero : le depot porte la date du jour, le message reste le meme chaque annee.
EXEC sp_executesql N'
INSERT INTO v2.CODE_EVE_PRO (R_CODEEVEPRO_VALEUR, R_CODEEVEPRO_LIBELLE_ECRAN, R_CODEEVEPRO_TYPE_EVE_PRO, R_CODEEVEPRO_CATEGORIE_DEPOT,
    R_CODEEVEPRO_AVEC_DEPOT_PC, R_CODEEVEPRO_AVEC_PIECE_NUMERISE_PCPRV, R_CODEEVEPRO_NATURE_DOC_GED, R_CODEEVEPRO_TYPE_DEPOSANT_GED) VALUES
    (''D15SAI'', ''Dépôt du banc avec dépôt PC'', ''1'', ''S15'', 1, 1, ''NAT15'', ''MANDATAIRE''),
    (''D15SANS'', ''Évènement du banc sans dépôt'', ''2'', NULL, 0, 0, NULL, NULL),
    (''D15FUT'', ''Évènement à venir du banc'', ''4'', NULL, 0, 0, NULL, NULL),
    (''D15OLD'', ''Évènement passé du banc'', ''2'', NULL, 0, 0, NULL, NULL);
INSERT INTO v2.CATEGORIE_DEPOT (R_CATEGORIED_VALEUR, R_CATEGORIED_TYPE_NUM_DEPOT) VALUES (''S15'', ''JD15S'');
INSERT INTO num.Compteur (Type, Annee, Structure, CodageAnnee, Lettre, TailleChrono, Debut) VALUES (''JD15S'', 2026, ''LC'', 4, ''DP15'', 5, 1);
IF NOT EXISTS (SELECT 1 FROM num.Compteur WHERE Type = ''DMD'')
    INSERT INTO num.Compteur (Type, Annee, Structure, CodageAnnee, Lettre, TailleChrono, Debut) VALUES (''DMD'', 2026, ''LAQC'', 2, ''D'', 5, 1);';

-- Les evenements deja la sur CHM DELTA, a des numeros d'ordre que la renumerotation de RIG v2 corrige (a venir d'abord, puis
-- par date : ProcedureCollective.cs:567-575) ; les saisies de depot (une validee sur CHM DELTA, une en attente sur une
-- prevention qu'aucun jeu ne pose, une interrompue sans dossier, une supprimee ecartee).
EXEC sp_executesql N'
INSERT INTO v2.EVENEMENT_PROCEDURE (EVNPR_ID_EVNPR, EVNPR_ID_PRCLL, EVNPR_NUM_ORDRE, EVNPR_CODE_EVE_PRO, EVNPR_DATE, EVNPR_SURVENU,
    EVNPR_DELAI_EXPIRE, EVNPR_DATE_MAXI) VALUES
    (1510341, 1400104, 7, ''D15OLD'', ''20200110'', 1, 0, NULL),
    (1510342, 1400104, 5, ''D15FUT'', NULL, 0, 0, ''20261231'');
INSERT INTO v2.DEMANDE (DMND_ID_DMND, DMND_NUM_DEMANDE, DMND_ETAT_DEMANDE, DMND_CODE_PROSS, DMND_EN_COURS, DMND_NOM, DMND_NUM_INDICATIF) VALUES
    (1510321, ''D1515100321'', ''V'', ''DEPPC'', 0, ''CHM DELTA'', ''1990P14104''),
    (1510322, ''D1515100322'', ''W'', ''DEPPR'', 0, ''PRV DEP ALPHA'', ''2027V15301''),
    (1510323, ''D1515100323'', ''I'', ''DEPPC'', 0, NULL, NULL),
    (1510324, ''D1515100324'', ''X'', ''DEPPC'', 0, ''CHM DELTA'', ''1990P14104'');
INSERT INTO v2.DOSSIER_DEMANDE (DSSDM_ID_DSSDM, DSSDM_ID_DMND, DSSDM_CODE_SEQUENCEUR, DSSDM_VALEUR_SEQUENCEUR) VALUES
    (1510331, 1510321, ''2P'', ''1400104''), (1510332, 1510322, ''2R'', ''1510399''), (1510334, 1510324, ''2P'', ''1400104'');';
